---@class Puzzle_3_HighLights 
local Puzzle_3_HighLights = Class('Puzzle_3_HighLights')



--- funtoy:
local KTool = CS.Engine.Lib.KTool
local IDComp = CS.Game.Native.Common.ID

---:
local Object = CS.UnityEngine.Object
local Transform = CS.UnityEngine.Transform
local Vector3 = CS.UnityEngine.Vector3
local Vector2Int = CS.UnityEngine.Vector2Int
local MeshRenderer = CS.UnityEngine.MeshRenderer
local SpriteRenderer = CS.UnityEngine.SpriteRenderer
local Color = CS.UnityEngine.Color
local Mathf = CS.UnityEngine.Mathf
local Time = CS.UnityEngine.Time


local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


-- ==================================================





-- ==================================================
   

function Puzzle_3_HighLights:__init()    
end


function Puzzle_3_HighLights:__delete()
end



function Puzzle_3_HighLights:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:
    self.color = Color( 1,1,1,1 )

    -- 把想要参与的 highLights 放到子层级中去, 或者自己就是 highLight 也行

    self.sRenderers = {} -- List<SpriteRenderer> table, 运行时自己查找 子元素填入体内...
    local srs = self.controller.gameObject:GetComponentsInChildren(typeof(SpriteRenderer),true) -- 包含自己 Array 
    for i=0, srs.Length-1 do 
        table.insert( self.sRenderers, srs[i] )
    end
end



function Puzzle_3_HighLights:Update()

    local time = Time.time % 10000
    local freq = 7.0

    local alpha = MapDecryptionMgr.Remap( 0.0, 1.0, 0.5, 1.0, Mathf.Sin(time * freq) )

    self.color.a = alpha

    for k,sr in pairs(self.sRenderers) do 

        sr.color = self.color
    end
end






function Puzzle_3_HighLights:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- =============================================================== Self -> ================================================================== -- 













return Puzzle_3_HighLights
